/**
 * Abstract parent to the Attribute, Campaign, Profession and Skilltype classes
 *
 * @abstract
 */
class DataObjectAbstract{

	/** @var {number|int} */
	#id;
	/** @var {Lang} */
	#lang;

	/**
	 * @param {number|int} $id
	 * @param {Lang|string} $lang
	 */
	constructor($id, $lang = Lang.EN){

		if(!this.constructor.IDS.includes($id)){
			throw new Error('invalid ID');
		}

		if(!($lang instanceof Lang)){
			$lang = new Lang($lang);
		}

		this.#id   = $id;
		this.#lang = $lang;
	}

	/**
	 * @returns {string}
	 * @codeCoverageIgnore
	 */
	static get CSS_CLASS(){
		return '';
	};

	/**
	 * @returns {number[]|int[]}
	 * @codeCoverageIgnore
	 */
	static get IDS(){
		return [];
	}

	/**
	 * @returns {Object<{}>}
	 * @codeCoverageIgnore
	 */
	static get NAME(){
		return {};
	}

	/** @returns {number|int} */
	get id(){
		return this.#id;
	}

	/** @returns {Lang} */
	get lang(){
		return this.#lang;
	}

	/**
	 * @param {Lang|string|null} $lang
	 * @returns {Lang}
	 * @protected
	 */
	_getLang($lang){

		if($lang === null){
			return this.lang;
		}

		if($lang instanceof Lang){
			return $lang;
		}

		return new Lang($lang);
	}

	/**
	 * Returns the readable name of the given ID
	 *
	 * @param {Lang|string|null} $lang
	 * @returns {string}
	 */
	getName($lang = null){
		$lang = this._getLang($lang);

		return this.constructor.NAME[this.id][$lang.id];
	}

	/**
	 * Checks whether the object ID is equal to the given ID
	 *
	 * @param {number|int} $id
	 * @returns {boolean}
	 */
	is($id){
		return this.id === $id;
	}

	/**
	 * Checks whether the object ID is in the given array of IDs
	 *
	 * @param {number[]|int[]} $ids
	 * @returns {boolean}
	 */
	in($ids){
		return $ids.includes(this.id);
	}

	/**
	 * @param {Lang|string|null} $lang
	 * @returns {HTMLElement|string|null}
	 */
	toHTML($lang = null){
		$lang = this._getLang($lang);

		// return an HTML snippet when DOM is not available
		if(typeof document === 'undefined'){
			return `<span class="${this.constructor.CSS_CLASS}" data-id="${this.id}"` +
			       ` data-lang="${$lang.id}">${this.getName($lang)}</span>`;
		}

		let el = document.createElement('span');
		el.className = this.constructor.CSS_CLASS;
		el.innerText = this.getName($lang);

		el.dataset.id   = String(this.id);
		el.dataset.lang = $lang.id;

		return el;
	}

}

/**
 * @created      11.07.2022
 * @author       smiley <smiley@chillerlan.net>
 * @copyright    2022 smiley
 * @license      MIT
 */

class PHPJS{

	/**
	 * @link  http://locutus.io/php/var/intval/
	 *
	 * @param {*} $var
	 * @param {number|int|null} $base
	 * @returns {number|int}
	 */
	static intval($var, $base = null){
		let tmp;
		let type = typeof($var);

		if(type === 'boolean'){
			return +$var;
		}

		if(type === 'string'){
			tmp = parseInt($var, $base || 10);

			return (isNaN(tmp) || !isFinite(tmp)) ? 0 : tmp;
		}

		if(type === 'number' && isFinite($var)){
			return $var|0;
		}

		return 0;
	}

	/**
	 * @link https://locutus.io/php/array/array_combine/
	 *
	 * @param {Array} keys
	 * @param {Array} values
	 * @returns {Object<{}>|boolean}
	 */
	static array_combine(keys, values){
		let newArray = {};
		let i = 0;
		// input sanitation
		if(
			// Only accept arrays or array-like objects
			typeof keys !== 'object'
			|| typeof values !== 'object'
			// Require arrays to have a count
			|| typeof keys.length !== 'number'
			|| typeof values.length !== 'number'
			|| !keys.length
			// number of elements does not match
			|| keys.length !== values.length
		){
			return false;
		}

		for(i = 0; i < keys.length; i++){
			newArray[keys[i]] = values[i];
		}

		return newArray;
	}

}

